// 실패 시 *APIError 를 반환하며, APIError.Decode 로 promotion.GetPromotionError 에 디코딩할 수 있습니다.
func (c *PaymentPromotionClient) GetPromotion(ctx context.Context, opts *promotion.GetPromotionOptions) (*promotion.Promotion, error) {
	if opts == nil {
		opts = &promotion.GetPromotionOptions{}
	}
	var result promotion.Promotion
	if err := c.client.do(ctx, http.MethodGet, "/promotions/"+url.PathEscape(opts.PromotionId), nil, nil, &result); err != nil {
		return nil, err
	}
	return &result, nil
}
